    --ds-gray-alpha-100: fade(@text, 6%);
    --ds-gray-alpha-200: fade(@text, 9%);
    --ds-gray-alpha-400: @surface0;
    --ds-gray-alpha-900: fade(@text, 61%);

    --themed-hover-bg: @subtext1;

    --ds-red-400: @red;
    --ds-red-800: @red;
    --ds-red-900: lighten(@red, 5%);

    --ds-blue-200: fade(@accent, 30%);
    --ds-blue-300: fade(@accent, 40%);
    --ds-blue-400: fade(@accent, 50%);
    --ds-blue-700: @accent;
    --ds-blue-900: @accent;

    --tw-gradient-top: transparent;

    svg {
      --geist-stroke: var(--geist-background) !important;
    }

    .geist-disabled img,
    .geist-disabled svg {
      filter: none;
    }

    .styled-scrollbar {
      scrollbar-color: @accent transparent;
    }

    .dark\:from-black,
    .from-white {
